<script setup lang="ts">
import {entryDisplayName as localizedEntryName} from '../runtime-presentation'

import { i18n as controlI18n } from '../../app/i18n'
const { t: controlText } = controlI18n.global

import MapFieldPicker from "../map-selection/MapFieldPicker.vue"
import {computed,ref,watch} from 'vue'
import type {RoomView,RoomCommand} from '../../online/protocol'
import type {M3Action} from '../../persistence/m3-world-schema'
import type {M3CastChoice} from '../../core/m3-spells'
import {useM3View} from './useM3View'
import M3DestinationPreview from './M3DestinationPreview.vue'
import SpatialStatus from '../SpatialStatus.vue'
import {runtimeDerived} from '../../core/runtime'
import {combatStats,freshTurn} from '../../core/combat-rules'
import {spatialCapabilities} from '../../core/m3-spatial'
const props=defineProps<{view:RoomView;busy:boolean}>(),emit=defineEmits<{command:[RoomCommand]}>()
const {people,state,scene,cat,world}=useM3View(()=>props.view)
const source=ref(''),x=ref(1),y=ref(1),height=ref(0),reactionsConfirmed=ref(false),mode=ref<'walk'|'climb'|'swim'|'fly'>('walk'),support=ref(''),note=ref('GM核对实际路线、落点和后果')
watch(people,p=>{if(!p.some(e=>e.id===source.value))source.value=p[0]?.id??''},{immediate:true})
const person=computed(()=>people.value.find(p=>p.id===source.value)),objectPerson=computed(()=>state.value?.entities.find(e=>e.id===source.value)),effects=computed(()=>person.value?.entity.state.effects??objectPerson.value?.effects??[])
const cap=computed(()=>person.value?.entity.c?runtimeDerived(person.value.entity.c,cat.value).spatialCapabilities:person.value?.entity.body?combatStats(person.value.entity.actor??{id:person.value.id,characterId:null,npc:person.value.entity.body,side:'neutral',initiative:null,surprised:false,turn:freshTurn()},world.value?.characters??[],cat.value).spatialCapabilities:spatialCapabilities({walk:0},effects.value))
watch(()=>person.value?.id,()=>{const p=person.value;x.value=p?.token.x??1;y.value=p?.token.y??1;height.value=p?.token.spatial?.height??0})
const effectId=ref(''),effectAction=ref<Extract<M3Action,{operation:'effect-action'}>['action']>('levitate'),option=ref<M3CastChoice['option']>('aquatic'),description=ref('')
const eventId=ref(''),stoneDamage=ref<'minor'|'partial'|'destroyed'>('partial'),diskId=ref(''),loadId=ref(''),portalId=ref(''),retracted=ref(false),knownTo=ref<string[]>([]),castId=ref(''),day=ref(0)
const pending=computed(()=>state.value?.events.filter(e=>e.status==='pending')??[])
const objects=computed(()=>state.value?.entities.filter(e=>e.sceneId===scene.value?.id)??[])
watch(()=>pending.value.find(e=>e.id===eventId.value),e=>{if(e){x.value=e.from.x;y.value=e.from.y;height.value=e.type==='return'?e.from.height:state.value?.environments.find(f=>f.sceneId===e.sceneId)?.floorHeight??0}})
const destination=()=>({x:x.value,y:y.value,height:height.value})
const send=(action:M3Action)=>emit('command',{kind:'m3-spatial',action})
</script>
<template>
 <details><summary>{{ controlText('spatial.spatialActions') }} <span v-if="pending.length">{{ controlText('quantity.itemSuffix', {p0:(pending.length)}) }}</span></summary>
  <label>{{ controlText('spatial.operator') }}<MapFieldPicker kind="entity"><select v-model="source"><option v-for="p in people" :key="p.id" :value="p.id">{{localizedEntryName(p)}}</option><option v-for="o in state?.entities.filter(o=>o.kind==='object'&&o.enabled)??[]" :key="o.id" :value="o.id">{{ controlText('spatial.objectLabel') }}{{localizedEntryName(o)}}</option></select></MapFieldPicker></label>
  <SpatialStatus :space="person?.token.spatial" :capabilities="cap" :effects="effects" />
  <div class="m3-form-grid"><label>{{ controlText('spatial.actualX') }}<input v-model.number="x" type="number" min="0" max="79" /></label><label>{{ controlText('spatial.actualY') }}<input v-model.number="y" type="number" min="0" max="79" /></label><label>{{ controlText('game.actualHeight') }}<input v-model.number="height" type="number" /></label></div>
  <M3DestinationPreview :scene-id="scene?.id" :disabled="busy" @select="p=>{x=p.x;y=p.y;height=p.height}" v-if="person&&scene" :from="person.token" :to="destination()" :feet="scene.grid.feet" :columns="scene.grid.columns" :rows="scene.grid.rows" :walls="scene.walls" :movement="true" :multiplier="['climb','swim'].includes(mode)&&cap[mode]===0?2:1" />
  <label>{{ controlText('domain.sourceLabel') }}<textarea v-model="note" rows="2" maxlength="2000" /></label>
  <details><summary>{{ controlText('spatial.movementMode') }}</summary><div class="m3-form-grid"><label>{{ controlText('game.movementMode') }}<select v-model="mode"><option value="walk">{{ controlText('game.walk') }}</option><option value="climb">{{ controlText('game.climb') }}</option><option value="swim">{{ controlText('game.swim') }}</option><option value="fly">{{ controlText('game.fly') }}</option></select></label><label>{{ controlText('spatial.supportLiquid') }}<MapFieldPicker kind="surface"><select v-model="support"><option value="">{{ controlText('spatial.noSupport') }}</option><option v-for="e in objects.filter(e=>['surface','liquid'].includes(e.kind))" :key="e.id" :value="e.id">{{localizedEntryName(e)}}</option></select></MapFieldPicker></label></div><button :disabled="busy||!source||!note.trim()" @click="send({operation:'move',entityId:source,to:destination(),mode,supportId:support||undefined,reactionsConfirmed,note})">{{ controlText('spatial.confirmMovement') }}</button><label><input v-model="reactionsConfirmed" type="checkbox" /> {{ controlText('spatial.opportunityHandled') }}</label></details>
  <details><summary>{{ controlText('spatial.effectOperations') }}</summary><label>{{ controlText('spatial.activeEffect') }}<MapFieldPicker kind="region" :locations="person||objectPerson?effects.map(f=>({id:f.id,name:f.name,kind:'region' as const,x:(person?.token??objectPerson)!.x,y:(person?.token??objectPerson)!.y,hitId:person?.token.id??objectPerson?.id})):[]"><select v-model="effectId"><option value="">{{ controlText('game.choose') }}</option><option v-for="f in effects.filter(f=>['alter-self','gaseous-form','levitate','water-walk','meld-into-stone'].includes(f.key))" :key="f.id" :value="f.id">{{localizedEntryName(f)}}</option></select></MapFieldPicker></label><label>{{ controlText('spatial.operation') }}<select v-model="effectAction"><option value="levitate">{{ controlText('spatial.levitate') }}</option><option value="alter-option">{{ controlText('spatial.alterSelf') }}</option><option value="end-form">{{ controlText('spatial.gaseousForm') }}</option><option value="water-cross">{{ controlText('spatial.waterWalk') }}</option><option value="stone-exit">{{ controlText('spatial.meldStone') }}</option></select></label><template v-if="effectAction==='alter-option'"><label>{{ controlText('domain.shapeOptions') }}<select v-model="option"><option value="aquatic">{{ controlText('domain.aquaticAdaptation') }}</option><option value="appearance">{{ controlText('domain.changeAppearance') }}</option><option value="weapons">{{ controlText('domain.naturalWeapons') }}</option></select></label><label v-if="option==='appearance'">{{ controlText('domain.appearance') }}<textarea v-model="description" rows="2" /></label></template><button :disabled="busy||!source||!effectId||!note.trim()" @click="send({operation:'effect-action',entityId:source,effectId,action:effectAction,choice:{option,description},to:destination(),note})">{{ controlText('spatial.confirmEffect') }}</button></details>
  <details v-if="effects.some(f=>f.key==='blink')"><summary>{{ controlText('spatial.blinkTiming') }}</summary><p class="muted">{{ controlText('spatial.blinkHint') }}</p><button :disabled="busy||!source" @click="send({operation:'turn-phase',entityId:source,phase:'end',note})">{{ controlText('spatial.endMyTurn') }}</button><button :disabled="busy||!source" @click="send({operation:'turn-phase',entityId:source,phase:'start',note})">{{ controlText('spatial.startMyTurn') }}</button></details><details><summary>{{ controlText('spatial.ropeSpace') }}</summary><label>{{ controlText('spatial.ropeEntrance') }}<MapFieldPicker kind="surface"><select v-model="portalId"><option value="">{{ controlText('game.choose') }}</option><option v-for="e in objects.filter(e=>e.kind==='portal'&&e.enabled)" :key="e.id" :value="e.id">{{ controlText('quantity.ropeOccupants', {p0:(localizedEntryName(e)),p1:(e.targetIds?.length??0),p2:(e.height),p3:(controlText('game.feet'))}) }}</option></select></MapFieldPicker></label><button :disabled="busy||!source||!portalId" @click="send({operation:'portal',entityId:source,portalId,enter:true,note})">{{ controlText('spatial.enterRope') }}</button><button :disabled="busy||!source||!portalId" @click="send({operation:'portal',entityId:source,portalId,enter:false,note})">{{ controlText('spatial.leaveRope') }}</button><label><input v-model="retracted" type="checkbox" /> {{ controlText('spatial.ropeInside') }}</label><label>{{ controlText('spatial.entranceKnowledge') }}<select v-model="knownTo" multiple size="3"><option v-for="p in people" :key="p.id" :value="p.id">{{localizedEntryName(p)}}</option></select></label><button :disabled="busy||!portalId" @click="send({operation:'portal-control',portalId,retracted,knownTo,note})">{{ controlText('spatial.saveRope') }}</button></details>
  <details><summary>{{ controlText('spatial.diskLoads') }}</summary><label>{{ controlText('spatial.disk') }}<MapFieldPicker kind="surface"><select v-model="diskId"><option value="">{{ controlText('game.choose') }}</option><option v-for="e in objects.filter(e=>e.kind==='disk'&&e.enabled)" :key="e.id" :value="e.id">{{localizedEntryName(e)}}</option></select></MapFieldPicker></label><label>{{ controlText('spatial.load') }}<MapFieldPicker kind="entity"><select v-model="loadId"><option value="">{{ controlText('game.choose') }}</option><option v-for="p in people" :key="p.id" :value="p.id">{{localizedEntryName(p)}}</option><option v-for="e in objects.filter(e=>e.kind==='object')" :key="e.id" :value="e.id">{{localizedEntryName(e)}} · {{e.weight}}{{ controlText('game.pounds') }}</option></select></MapFieldPicker></label><button :disabled="busy||!diskId||!loadId" @click="send({operation:'disk',diskId,action:'load',entityId:loadId,note})">{{ controlText('spatial.loadDisk') }}</button><button :disabled="busy||!diskId||!loadId" @click="send({operation:'disk',diskId,action:'unload',entityId:loadId,note})">{{ controlText('spatial.unload') }}</button><button :disabled="busy||!diskId" @click="send({operation:'disk',diskId,action:'follow',to:destination(),note})">{{ controlText('spatial.followRoute') }}</button></details>
  <details :open="pending.length>0"><summary>{{ controlText('spatial.pendingSpatial') }} {{pending.length}}</summary><p v-if="!pending.length" class="muted">{{ controlText('spatial.noSpatial') }}</p><template v-else><label>{{ controlText('spatial.savedEvent') }}<select v-model="eventId"><option value="">{{ controlText('game.choose') }}</option><option v-for="e in pending" :key="e.id" :value="e.id">{{localizedEntryName(people.find(p=>p.id===e.entityId))??e.entityId}} · {{e.type}} · {{e.note}}</option></select></label><label v-if="pending.find(e=>e.id===eventId)?.type==='stone-damage'">{{ controlText('spatial.stoneDamage') }}<select v-model="stoneDamage"><option value="minor">{{ controlText('spatial.stoneMinor') }}</option><option value="partial">{{ controlText('spatial.stonePartial') }}</option><option value="destroyed">{{ controlText('spatial.stoneDestroyed') }}</option></select></label><button :disabled="busy||!eventId||!note.trim()" @click="send({operation:'event',eventId,to:destination(),stoneDamage,note})">{{ controlText('spatial.confirmConsequence') }}</button></template></details>
  <details><summary>{{ controlText('spatial.auraDays') }}</summary><label>{{ controlText('spatial.resolvedCast') }}<select v-model="castId"><option value="">{{ controlText('game.choose') }}</option><option v-for="c in state?.casts.filter(c=>c.settled&&c.spellId==='arcanist-s-magic-aura')??[]" :key="c.castId" :value="c.castId">{{c.castId.slice(0,8)}} · {{localizedEntryName(people.find(p=>p.id===c.action.casterId))}}</option></select></label><label>{{ controlText('spatial.adventureDay') }}<input v-model.number="day" type="number" min="0" max="100000" /></label><button :disabled="busy||!castId" @click="send({operation:'aura-day',castId,day,note})">{{ controlText('spatial.registerDay') }}</button></details>
 </details>
</template>
